import { StyleSheet } from "@/lib/pdf-primitives";
import type { PdfcnTheme } from "@/types/pdf-themes";

/**
 * Creates all columns styles derived from the active theme.
 * @param t - The resolved PdfcnTheme instance.
 */
export const createColumnsStyles = (t: PdfcnTheme) => {
  const { spacing, fontWeights } = t.primitives;

  return StyleSheet.create({
    column: {
      flexBasis: 0,
      flexGrow: 1,
      flexShrink: 1,
      minWidth: 0,
    },
    container: {
      flexDirection: "row",
      marginBottom: spacing[3],
    },
    divider: {
      flexShrink: 0,
      width: 0.5,
    },
    emphasis: {
      fontWeight: fontWeights.bold,
    },
    line: {
      color: t.colors.foreground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: t.typography.body.fontSize,
      lineHeight: t.typography.body.lineHeight,
    },
    spacer: {
      flexShrink: 0,
    },
  });
};

import { Strong } from "@formepdf/react";

import {
  usePdfcnTheme,
  useSafeMemo,
} from "@/components/pdf/theme-provider";
import {
  View,
  Text as PDFText,
} from "@/lib/pdf-primitives";
import type { Style } from "@/lib/pdf-primitives";
import { resolveColor } from "@/lib/resolve-color";

import { createColumnsStyles } from "./columns.styles";
import type { ColumnsProps } from "./columns.types";
import { parseEmphasis, RATIO_FLEX } from "./columns.utils";

const Column = ({
  text,
  flex,
  lineStyle,
}: {
  text: string;
  flex: number;
  lineStyle: Style;
}) => (
  <View style={{ flexBasis: 0, flexGrow: flex, flexShrink: 1, minWidth: 0 }}>
    {text.split("\n").map((line, i) => (
      <PDFText key={`${i}-${line.length}`} style={lineStyle}>
        {line.length === 0
          ? " "
          : parseEmphasis(line).map((segment, j) =>
              // Raw <Strong> required: Forme only produces styled runs from
              // elements whose type it recognises (Text, Strong, Em…).
              segment.bold ? (
                <Strong key={`${i}-${j}`}>{segment.text}</Strong>
              ) : (
                segment.text
              )
            )}
      </PDFText>
    ))}
  </View>
);

export const Columns = ({
  left,
  right,
  ratio = "1:1",
  gap,
  accentColor,
  style,
}: ColumnsProps) => {
  const theme = usePdfcnTheme();
  const styles = useSafeMemo(() => createColumnsStyles(theme), [theme]);

  const [leftFlex, rightFlex] = RATIO_FLEX[ratio];
  const columnGap = gap ?? theme.primitives.spacing[3];
  const accent = accentColor
    ? resolveColor(accentColor, theme.colors)
    : undefined;
  const containerStyles: Style[] = [styles.container];
  if (style) {
    containerStyles.push(style);
  }

  return (
    <View style={containerStyles}>
      <Column flex={leftFlex} lineStyle={styles.line} text={left} />
      {accent ? (
        <View
          style={[
            styles.divider,
            {
              alignSelf: "stretch",
              backgroundColor: accent,
              marginHorizontal: columnGap / 2 - 0.25,
            },
          ]}
        />
      ) : (
        <View style={[styles.spacer, { width: columnGap }]} />
      )}
      <Column flex={rightFlex} lineStyle={styles.line} text={right} />
    </View>
  );
};

import type { Style } from "@/lib/pdf-primitives";

import type { ColumnsRatio } from "./columns.utils";

/**
 * Side-by-side two-column text with equal or weighted widths.
 * Each column is multi-line text; `**segment**` renders bold.
 * Props - `left` | `right` | `ratio` | `gap` | `accentColor` | `renderingBase` | `style`
 * @see {@link ColumnsProps}
 */
export interface ColumnsProps {
  /** Left column text. `\n` splits lines; `**segment**` renders bold. */
  left: string;
  /** Right column text. `\n` splits lines; `**segment**` renders bold. */
  right: string;
  /**
   * Width ratio between the columns.
   * @default '1:1'
   */
  ratio?: ColumnsRatio;
  /** Horizontal gap between columns in points. Defaults to the theme gap. */
  gap?: number;
  /**
   * Accent color for a vertical rule between the columns. Omit for none.
   */
  accentColor?: string;
  renderingBase?: "takumi" | "forme";
  style?: Style;
}

/**
 * Width ratio between the left and right column.
 * `"1:1"` equal, `"2:1"` wide left, `"1:2"` wide right.
 */
export type ColumnsRatio = "1:1" | "2:1" | "1:2";

/** Flex grow factors applied to `[left, right]` for a given ratio. */
export const RATIO_FLEX: Record<ColumnsRatio, [number, number]> = {
  "1:1": [1, 1],
  "1:2": [1, 2],
  "2:1": [2, 1],
};

/** A piece of column text, optionally bold (`**segment**`). */
export interface InlineSegment {
  text: string;
  bold: boolean;
}

const BOLD_RE = /\*\*([^*]+)\*\*/g;

/**
 * Splits one line of column text into plain and bold segments.
 * `"Total: **$120**"` → `[{text:"Total: ",bold:false},{text:"$120",bold:true}]`
 */
export const parseEmphasis = (line: string): InlineSegment[] => {
  const segments: InlineSegment[] = [];
  let cursor = 0;
  for (const match of line.matchAll(BOLD_RE)) {
    const index = match.index ?? 0;
    if (index > cursor) {
      segments.push({ bold: false, text: line.slice(cursor, index) });
    }
    segments.push({ bold: true, text: match[1] ?? "" });
    cursor = index + match[0].length;
  }
  if (cursor < line.length) {
    segments.push({ bold: false, text: line.slice(cursor) });
  }
  return segments;
};
